css:
.glass-dock { --dock-control-hover-bg: color-mix(in oklab, var(--dock-fg-on-aurora, var(--foreground)) 6.5%, transparent); --dock-control-active-bg: color-mix(in oklab, var(--dock-fg-on-aurora, var(--foreground)) 10%, transparent); --glass-capsule-fill: var(--dock-control-active-bg); }
:root:not(.dark) .glass-dock:not(.dark) { --glass-level: 1; }
.dark .glass-dock, .glass-dock.dark { --glass-level: 0.7; }
